// swift-tools-version: 5.9
// PlayDropCore: the UniFFI Swift bindings over playdrop-ffi plus the Rust core as an
// XCFramework. Both are produced by `apps/ios/scripts/build-core.sh` and are not committed:
//   Sources/PlayDropCore/PlayDropCore.swift   generated by uniffi-bindgen (module PlayDropCore)
//   PlayDropCoreFFI.xcframework/              libplaydrop_ffi.a for aarch64-apple-ios and
//                                             aarch64-apple-ios-sim with PlayDropCoreFFI.h
//                                             and its module map as the framework headers
import PackageDescription

let package = Package(
    name: "PlayDropCore",
    platforms: [.iOS(.v17)],
    products: [
        .library(name: "PlayDropCore", targets: ["PlayDropCore"]),
    ],
    targets: [
        .binaryTarget(
            name: "PlayDropCoreFFI",
            path: "PlayDropCoreFFI.xcframework"
        ),
        .target(
            name: "PlayDropCore",
            dependencies: ["PlayDropCoreFFI"],
            path: "Sources/PlayDropCore",
            exclude: [".gitkeep"]
        ),
    ]
)
